namespace { define( 'ABSPATH', '/tmp/wp/' ); function sanitize_key( string $value ): string { return strtolower( preg_replace( '/[^a-z0-9_\-]/', '', $value ) ?? '' ); } function absint( mixed $value ): int { return abs( (int) $value ); } function assert_true( bool $ok, string $message ): void { if ( ! $ok ) { fwrite( STDERR, "FAIL: {$message}\n" ); exit( 1 ); } } }
